import json
from fractions import Fraction

# Exact computations from the stated game state.
friend_count = 1 + 2
diameter = Fraction(29)
box = tuple(Fraction(s) for s in ("39.6", "24.3", "31.6"))

# A sphere fits in a rectangular box exactly when its diameter
# does not exceed any of the box's three dimensions.
basketball_fits = all(diameter <= side for side in box)

# Restrict inference to the dependency slice of the queried conclusion.
# Literals are (proposition, polarity). Missing facts are not negations.
facts = set()
if friend_count < 4:
    facts.add(("duck_fewer_than_four_friends", True))
if basketball_fits:
    facts.add(("duck_basketball_fits_box", True))

rules = {
    "Rule2": (
        {("duck_has_sharp_object", True)},
        ("duck_wants_butterfly", True),
    ),
    "Rule3": (
        {("duck_watching_movie_released_after_WW2_started", True)},
        ("duck_wants_butterfly", False),
    ),
    "Rule4": (
        {("duck_wants_butterfly", True)},
        ("otter_hides_cards_from_badger", True),
    ),
    "Rule7": (
        {("duck_fewer_than_four_friends", True)},
        ("duck_wants_butterfly", True),
    ),
    "Rule9": (
        {("duck_basketball_fits_box", True)},
        ("duck_wants_butterfly", False),
    ),
}
preferred = {
    ("Rule3", "Rule2"),
    ("Rule3", "Rule7"),
    ("Rule9", "Rule2"),
    ("Rule9", "Rule7"),
}

known = set(facts)
seen = set()
while True:
    state = frozenset(known)
    if state in seen:
        print(json.dumps({
            "final_answer": "UNSUPPORTED",
            "evidence": {"reason": "Inference did not reach a fixed point"}
        }, separators=(",", ":")))
        break
    seen.add(state)

    applicable = {
        name for name, (antecedents, _) in rules.items()
        if antecedents <= known
    }
    accepted = set()
    for name in applicable:
        conclusion = rules[name][1]
        opposite = (conclusion[0], not conclusion[1])
        defeated = any(
            (other, name) in preferred and rules[other][1] == opposite
            for other in applicable
        )
        if not defeated:
            accepted.add(name)

    updated = facts | {rules[name][1] for name in accepted}
    if updated == known:
        query = ("otter_hides_cards_from_badger", True)
        opposite = (query[0], False)
        if query in known and opposite not in known:
            answer = "proved"
        elif opposite in known and query not in known:
            answer = "disproved"
        elif query not in known and opposite not in known:
            answer = "unknown"
        else:
            answer = "UNSUPPORTED"

        print(json.dumps({
            "final_answer": answer,
            "evidence": {
                "duck_friend_count": friend_count,
                "basketball_fits_box": basketball_fits,
                "limiting_box_dimension_inches": str(min(box)),
                "applicable_rules": sorted(applicable),
                "accepted_rules": sorted(accepted),
                "duck_wants_butterfly": (
                    ("duck_wants_butterfly", True) in known
                ),
                "otter_hides_cards": query in known
            }
        }, separators=(",", ":")))
        break
    known = updated
